-- This script upserts deterministic records and does not delete manual rows.

begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "42bd5c10-79ab-504c-ab72-0a629ea6f0b3", "feature_slug": "forms", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Forms let you control exactly what information you collect from members — from basic contact details to custom questions about preferences and interests. You choose which fields are required, who sees which fields based on their persona, and what consent you collect.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member can''t complete signup\" | Check if all required fields are visible (`visible_to_user = true`). Check persona filtering — if a field is restricted to personas the member hasn''t selected, it''s hidden but may still be required upstream |\n| \"A field isn''t showing for some members\" | Field has `persona_ids` set — only matching personas see it. Or `active_status = false`. Or a conditional rule is hiding it |\n| \"Member says form is asking questions again\" | New required fields were added after their initial signup → `complete_profile_existing` shows only the new fields |\n| \"Custom field data is missing\" | Check USER_PROFILE form template status — must be `published`. Check that `form_submission` exists for the user |\n| \"Consent options not appearing\" | Consent items configured in Consent Settings — separate from Profile Form Settings. Check consent config |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L178 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8b27adad5cb1bf7d8a168ae2b9f8a7904f11ba99fcce36edbe12c33115c29003", "truncated": false}, "is_active": true}, {"id": "f2b467c1-e872-5692-acc8-966ae725cb4f", "feature_slug": "forms", "title": "1. Overview", "content": "Forms control what data the platform collects from members — during signup and on their profile page. Two distinct systems work together: **default fields** for standard profile data (name, email, phone, address) and **custom fields** for merchant-defined questions (interests, occupation, preferences). Both appear as a single unified form to the member, but are stored and configured separately.\n\nDefault fields map directly to columns in `user_accounts` and `user_address`. Custom fields live in a flexible schema: merchants create a `USER_PROFILE` form template, organize fields into groups, and the system stores responses in `form_submissions` and `form_responses`. This separation means merchants can extend the profile without schema changes — they add fields through the admin UI, and those fields appear on the next signup.\n\nThe form system also handles PDPA consent collection (privacy notices, marketing opt-ins, communication channel preferences) and supports persona-aware field filtering — different member types can see different fields. Conditional logic lets fields show, hide, or become required based on other field values, enabling dynamic forms without code.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5692138f7ff76c72f72f71aba51fad2cfe95cb9f79f4c951b6bd29753dcc5d83", "truncated": false}, "is_active": true}, {"id": "74da9f5e-bbd1-5369-bc5d-b45958de7ee5", "feature_slug": "forms", "title": "8. Related Features", "content": "| Feature | Connection to Forms |\n|---|---|\n| Tags & Personas | Persona selection during signup filters which form fields appear. See `Tag_and_Persona.md`. |\n| Translation | Field labels, placeholders, group names, and PDPA content support multi-language rendering via the translation system. |\n| Tier | Profile completion (form fields) can be a prerequisite for tier-gated features. |\n| Rewards | Persona-aware field filtering affects eligibility when persona-aware features are active. See `Reward.md`. |\n| Activity/Earning | Custom field data (e.g., store preference) can feed into activity-based earning segmentation. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L271 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5ba5dd75349580d781af5f885fd66291c2d026cdb76e5d7306b37cebd6fe6d29", "truncated": false}, "is_active": true}, {"id": "2b32b5db-d64f-59dc-91dd-9384c05d02cc", "feature_slug": "forms", "title": "Architecture Overview", "content": "Two distinct field systems work together:\n\n\n| System             | Purpose                                                    | Storage                              | Configuration                    |\n| ------------------ | ---------------------------------------------------------- | ------------------------------------ | -------------------------------- |\n| **Default Fields** | Standard user profile fields (email, phone, name, address) | `user_accounts`, `user_address`      | `user_field_config`              |\n| **Custom Fields**  | Merchant-defined additional fields                         | `form_submissions`, `form_responses` | `form_templates` → `form_fields` |\n\n\nBoth systems share the same frontend API and rendering logic.\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Forms.md#L3 Architecture Overview", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5e5ba1da44ccca62da86fc1241e506033ee3c55c5030b9fd52b052fbf07404b3", "truncated": false}, "is_active": true}, {"id": "101765f3-a31f-5e46-a160-52e18f7949d0", "feature_slug": "forms", "title": "Frontend Integration (WeWeb)", "content": "### State Management\n\nStore API response in a WeWeb variable. All handlers modify this variable directly.\n\n```javascript\nconst state = variables[''45691153-f0a5-42fa-ac9a-5729a9853be2''];\n```\n\n### Form Field Handler\n\nHandles `default_fields_config`, `custom_fields_config`, and `persona` updates with 5-second debounce.\n\n```javascript\n// Parameters: object_type, field_key, group_id, value\n\nconst objectType = context.parameters[''object_type''];\nconst fieldKey = context.parameters[''field_key''];\nconst groupId = context.parameters[''group_id''];\nconst valueParam = context.parameters[''value''];\n\nconst rawValue = valueParam !== undefined && valueParam !== null ? valueParam : event;\nconst newValue = typeof rawValue === ''object'' ? JSON.parse(JSON.stringify(rawValue)) : rawValue;\n\nconst debounceKey = `debounce_${fieldKey}`;\nconst debounceDelay = 5000;\n\nif (window[debounceKey]) {\n  clearTimeout(window[debounceKey]);\n}\n\nreturn new Promise((resolve) => {\n  window[debounceKey] = setTimeout(() => {\n    const target = variables[''45691153-f0a5-42fa-ac9a-5729a9853be2''];\n    \n    if (!target) {\n      resolve(null);\n      return;\n    }\n\n    if (objectType === ''persona'') {\n      target.persona.selected_persona_id = newValue;\n    } \n    else if (objectType === ''custom_fields_config'') {\n      const group = target.custom_fields_config.find(g => g.id === groupId);\n      if (group) {\n        const field = group.fields.find(f => f.field_key === fieldKey);\n        if (field) field.value = newValue;\n      }\n    } \n    else if (objectType === ''default_fields_config'') {\n      for (const group of target.default_fields_config) {\n        const field = group.fields.find(f => f.field_key === fieldKey);\n        if (field) {\n          field.value = newValue;\n          break;\n        }\n      }\n    }\n\n    resolve(true);\n  }, debounceDelay);\n});\n```\n\n### PDPA Handler\n\nHandles consent accordion expand/collapse and acceptance toggles.\n\n```javascript\n// Parameters: type, action, section_id, option_id\n\nconst type = context.parameters[''type''];\nconst action = context.parameters[''action''];\nconst section_id = context.parameters[''section_id''];\nconst option_id = context.parameters[''option_id''];\n\nconst pdpaState = variables[''45691153-f0a5-42fa-ac9a-5729a9853be2''];\n\n// EXPAND: Toggle accordion section\nif (action === ''expand'') {\n  pdpaState.selected_section = (pdpaState.selected_section === section_id) ? null : section_id;\n  return pdpaState;\n}\n\n// ACCEPT_ALL: Accept all consents and select all options\nif (action === ''accept_all'') {\n  pdpaState.pdpa.forEach(section => {\n    section.isAccepted = true;\n    if (section.options && section.options.length > 0) {\n      section.options.forEach(opt => opt.selected = true);\n    }\n  });\n  return pdpaState;\n}\n\n// ACCEPT: Toggle individual consent or option\nif (action === ''accept'') {\n  const sectionIndex = pdpaState.pdpa.findIndex(item => item.id === section_id);\n  if (sectionIndex === -1) return pdpaState;\n  \n  const section = pdpaState.pdpa[sectionIndex];\n\n  if (type === ''notice'' || type === ''text_content'') {\n    // Simple toggle\n    section.isAccepted = !section.isAccepted;\n  }\n  else if (type === ''checkbox_options'') {\n    if (option_id) {\n      // Individual option toggle\n      const optionIndex = section.options.findIndex(opt => opt.id === option_id);\n      if (optionIndex !== -1) {\n        section.options[optionIndex].selected = !section.options[optionIndex].selected;\n      }\n      // Master checkbox = true only if ALL options selected\n      section.isAccepted = section.options.every(opt => opt.selected === true);\n    } \n    else {\n      // Master checkbox toggle - cascades to all options\n      const newValue = !section.isAccepted;\n      section.isAccepted = newValue;\n      section.options.forEach(opt => opt.selected = newValue);\n    }\n  }\n  \n  return pdpaState;\n}\n\nreturn pdpaState;\n```\n\n### PDPA Types\n\n\n| `interaction_type` | `type`             | UI Behavior            |\n| ------------------ | ------------------ | ---------------------- |\n| `notice`           | `notice`           | Read-only, no checkbox |\n| `optional`         | `text_content`     | Checkbox, optional     |\n| `required`         | `text_content`     | Checkbox, mandatory    |\n| (channels/topics)  | `checkbox_options` | Multiple checkboxes    |\n\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Forms.md#L566 Frontend Integration (WeWeb)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "89ae7867b0756ebf3b1365e44b58615c65c126463031c61016606abc24134638", "truncated": false}, "is_active": true}, {"id": "f0a5ba13-f6e0-5d9e-b3d3-f1d095b57b17", "feature_slug": "forms", "title": "Forms & User Profile Domain Reference", "content": "**Keywords:** form, survey, field, custom field, default field, profile, user field config, form template, form field, form response, form submission, field type, select, multi-select, conditional field, PDPA, consent, address\n**Source:** `Forms.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `bff_get_user_profile_template(p_language, p_mode)` | `p_language`, `p_mode (''new''/''edit'')` | Full form config with fields, options, conditions, PDPA | 206–307 |\n| `bff_save_user_profile(p_data)` | `p_data (jsonb)` | `{ success, user_id, is_new_user }` | 309–344 |\n| `bff_admin_update_member_profile(p_user_id, p_data)` | `p_user_id (uuid)`, `p_data (jsonb)` | Admin update for allowed default/custom profile fields; address upsert uses `(user_id, merchant_id)` | — |\n| `bff_admin_get_form_submission_data(p_form_id, p_user_id)` | `p_form_id (uuid)`, `p_user_id (uuid)` | `{ success, data: { submission_id, submitted_at, status, source, values: {field_key: value} } }` | — |\n| `bff_user_get_surveys(p_language)` | `p_language` | Published surveys with `reward_preview` and `user_state` | Survey Completion Rewards |\n| `bff_user_get_survey_details(p_form_identifier, p_language)` | `p_form_identifier`, `p_language` | Survey form detail with fields/options/placeholders plus `reward_preview` and `user_state` | Survey Completion Rewards |\n| `bff_user_submit_survey(p_form_id, p_submission_data, p_source, p_source_id, p_ref_userid, p_tel)` | `p_form_id`, keyed submission JSON, source metadata | Submission result with `reward_outcome` | Survey Completion Rewards |\n| `bff_get_form_details(p_form_id, p_mode)` | `p_form_id`, `p_mode (''new''/''edit'')` | Form admin payload — includes `data.form.allow_bulk_import` and `data.metadata.allow_bulk_import_locked` (true for USER_PROFILE) | — |\n| `bff_upsert_form(p_data jsonb)` | full form payload incl. `form.allow_bulk_import` | Saves form; persists `allow_bulk_import` flag (USER_PROFILE auto-true) | — |\n**Key Business Rules (summary):**\n- Default fields stored in `user_accounts` / `user_address`; custom fields in `form_responses`\n- `user_address` is merchant-scoped; one editable profile address is keyed by `(user_id, merchant_id)`, not `user_id` alone\n- USER_PROFILE form (code = `USER_PROFILE`) is the special signup/profile form\n- `persona_ids` on fields: show only for specific personas (NULL = universal)\n- Conditional logic: field visibility/requirement changes based on other field values\n- PDPA types: `notice` (read-only), `text_content` (single checkbox), `checkbox_options` (multiple)\n- Cache: 5-min TTL, structure cached, values always live\n- Survey submission limits: per-user and total caps via `transaction_limits` with `entity_type=''form''`, enforced in `submit_form_public`. Skipped for USER_PROFILE and anonymous submissions.\n- User survey APIs only expose `form_templates.status=''published''` and `form_category=''survey''`; rewards are displayed from the hidden `system_survey_reward:{form_id}` workflow config.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/forms-user-profile.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "b64351699ce1582458224d1485a92a0807e456bdeab0313d697caed7012e1c2e", "truncated": false}, "is_active": true}, {"id": "dbc12453-c970-58fc-a52f-eb15a52c4c4a", "feature_slug": "forms", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Default field `active_status = false` | Field absent from signup form |\n| Default field `visible_to_user = false`, `is_required = true` | Save fails — required but invisible |\n| Custom field `persona_ids = [\"uuid1\"]`, member has different persona | Field not rendered |\n| `persona_ids = null` or `[]` | Field visible to all members |\n| Condition: source=occupation, operator=equals, value=student, target=income, action=hide | When occupation=\"student\", income field hidden |\n| Condition action=require | Target field becomes mandatory when condition matches |\n| `require_at_least_one = true` on group | Submission fails if all fields in group are empty |\n| USER_PROFILE template status=draft | No custom fields appear in signup |\n| PDPA consent `is_mandatory = true`, not accepted | \"Next\"/\"Confirm\" blocked |\n| mode=new | All field values are null (fresh form) |\n| mode=edit | Field values populated from database |\n\n**Business rules as assertions:**\n\n- ASSERT: Form step sequence is persona → default_field → custom_field → pdpa; empty steps are skipped\n- ASSERT: New user (`complete_profile_new`) gets full form with all values null\n- ASSERT: Returning user with `is_signup_form_complete = false` gets full form with existing values\n- ASSERT: Returning user with `is_signup_form_complete = true` and new required fields gets only those fields\n- ASSERT: Conditional logic evaluates on every field change — show/hide/enable/disable/require update instantly\n- ASSERT: Persona selection filters both default and custom fields in subsequent steps\n- ASSERT: \"Accept All\" on PDPA toggles all consents and all sub-options to true\n- ASSERT: Checkbox_options master toggle cascades to all child options; unchecking any child unchecks master\n- ASSERT: Field value changes debounce at 5 seconds before updating state\n- ASSERT: If `missing_data` is null/empty, Retry button shown — form never auto-saves empty data\n\n**Error states to test:**\n\n- `bff-auth-complete` fails to load form → \"Could not load the registration form\" + Retry button\n- Required field left empty → Next button validation blocks advancement\n- Mandatory consent not accepted → cannot proceed past PDPA step\n- Phone edit requires OTP re-verification\n- Concurrent profile edit (two tabs) — last save wins", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L178 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e755b77d46852d7f2dcf46afedfb05b1724ae4c05208015e3d7d7f8580bad011", "truncated": false}, "is_active": true}, {"id": "f2bcfb2b-85bb-5407-aad3-51f1679ac7e7", "feature_slug": "forms", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current Route | Data Source |\n|---|---|---|\n| Signup Drawer | Bottom-sheet on any page | `bff-auth-complete` edge function → `bff_get_user_profile_template(mode=''new'')` |\n| Edit Profile Drawer | Bottom-sheet on `/profile` | `bff_get_user_profile_template(mode=''edit'')` |\n| Profile Page | `/profile` | `get_user_summary()` |\n\n### 5a. Signup Flow (New User)\n\n1. Member authenticates (LINE / phone OTP) → `bff-auth-complete` returns `next_step = complete_profile_new` with full form in `missing_data`\n2. **Persona step** — grid of persona avatars grouped by type; member selects one (skipped if merchant doesn''t use personas)\n3. **Default fields step** — renders fields from `default_fields_config` dynamically: text inputs, email/phone fields, date pickers, select dropdowns. Terms acceptance row at bottom\n4. **Custom fields step** — renders merchant-defined fields from `custom_fields_config`. Conditional logic evaluated in real-time: changing a source field triggers show/hide/enable/disable/require on target fields\n5. **PDPA step** — consent accordion: notice items (read-only), text_content items (single checkbox), checkbox_options (channel/topic multi-checkboxes). \"Accept All\" button toggles everything\n6. **\"Next\"** validates current step (required fields, mandatory consents) → advances to next step. **\"Back\"** returns to previous\n7. **\"Confirm\"** on last step → `bff_save_user_profile` saves all data atomically → drawer closes\n\n### 5b. Returning User — Incomplete Profile\n\n1. Authenticated user with `is_signup_form_complete = false` → `bff-auth-complete` returns `complete_profile_existing` with full form and pre-filled values\n2. Same multi-step flow as 5a but with existing values populated\n\n### 5c. Returning User — New Required Fields\n\n1. Authenticated user with `is_signup_form_complete = true` but new required fields added post-signup → `complete_profile_existing` with only missing required fields\n2. Abbreviated form — only the fields that need filling\n\n### 5d. Edit Profile\n\n1. From **Profile Page**, tap edit icon → **Edit Profile Drawer** opens\n2. Fetches `bff_get_user_profile_template(mode=''edit'')` — structure from cache, values from database\n3. Reuses same `DynamicFormFields` component from signup — same field rendering, conditional logic, validation\n4. Phone editing triggers nested **Edit Phone Dialog** with OTP verification\n5. Save via `bff_save_user_profile`\n\n### 5e. Consent Management\n\n1. From **Profile Page** → Settings → **Consent Management** drawer\n2. Shows current consent state with accordion UI (same `ConsentSection` component as signup)\n3. Save via `bff_save_user_profile` with pdpa payload", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/forms.md#L132 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "db8f8ae01c409ae8202c0a5f5548396b4677ccd69fdcdc87cae77fe352141f85", "truncated": false}, "is_active": true}, {"id": "b178aa66-b03e-5d6b-8bba-6c47fc0f6f3d", "feature_slug": "forms", "title": "6b. For Marketing", "content": "**Value proposition:** Forms are the data collection layer for personalization. Every field captured during signup feeds into segmentation — persona selection drives which fields appear (and which promotions, rewards, and tier benefits a member sees). Custom fields like \"interests\" and \"occupation\" enable targeted campaigns without surveys.\n\n**Use-case stories:**\n\n1. **Fashion retailer** — Custom multi-select \"Style Preferences\" field (Casual, Formal, Streetwear) appears during signup. Marketing uses responses to segment members for targeted push notifications about relevant collections.\n\n2. **B2B distributor** — Persona selection (Corporate, SME, Individual) at signup determines which default fields appear (Corporate sees \"Company Name\" and \"Tax ID\", Individual doesn''t). Different earn rates and reward catalogs per persona.\n\n3. **Restaurant chain** — Conditional field: when \"Dietary Preference\" = \"Vegetarian\", a follow-up \"Allergen Info\" field appears. Data feeds into personalized menu recommendations and birthday reward selection.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/forms.md#L178 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "forms", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "18d03bc4adf5f440e2697d1282889a2396ec6a6534105565f704ed0f817ca22f", "truncated": false}, "is_active": true}, {"id": "db12e7a7-f375-5d1d-89d7-4603e5bd113c", "feature_slug": "internal-knowledge", "title": "Implementation Status", "content": "Implemented in Supabase with `internal_knowledge`-prefixed database objects.\n\n### Tables\n\n```text\ninternal_knowledge_feature_items\ninternal_knowledge_blocks\ninternal_knowledge_type_templates\n```\n\n### Enum Types\n\n```text\ninternal_knowledge_item_type\ninternal_knowledge_type\ninternal_knowledge_perspective\ninternal_knowledge_output_use\ninternal_knowledge_scope\n```\n\n### Functions\n\nRead functions:\n\n```text\ninternal_knowledge_get_feature_tree\ninternal_knowledge_get_feature_context\ninternal_knowledge_search_feature_knowledge\ninternal_knowledge_get_related_features\ninternal_knowledge_list_knowledge_type_templates\n```\n\nEdit and authoring functions:\n\n```text\ninternal_knowledge_create_feature_item\ninternal_knowledge_update_feature_item\ninternal_knowledge_create_knowledge_block\ninternal_knowledge_update_knowledge_block\ninternal_knowledge_suggest_block_metadata\ninternal_knowledge_validate_knowledge_block\n```\n\nRead functions are granted to `authenticated` and `service_role`. Edit functions are granted to `service_role`.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "docs/FEATURE_KNOWLEDGE_DATABASE_PLAN.md#L9 Implementation Status", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "internal-knowledge", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "edbc48d905d515743c1da82daea833ea8660cf8a34914b20eb9f811f2a846206", "truncated": false}, "is_active": true}, {"id": "f320f907-b9be-583d-9cbf-136bf18844a5", "feature_slug": "internal-knowledge", "title": "Table: `internal_knowledge_feature_items`", "content": "One table stores domains, features, and sub-features.\n\n### Columns\n\n```text\nid\nparent_id\nslug\nname\nitem_type\ndescription\nsort_order\nmetadata\nis_active\ncreated_at\nupdated_at\n```\n\n### `item_type` Values\n\n```text\ndomain\nfeature\nsub_feature\n```\n\nDefinitions:\n\n```text\ndomain\nLarge product area, e.g. Loyalty, Customer Service, AMP.\n\nfeature\nMajor feature, e.g. Reward, Currency, Purchase Transaction.\n\nsub_feature\nSmaller part of a feature, e.g. Reward Redemption, Reward Groups, Dynamic Reward Points.\n```\n\nDo not use item types such as `screen`, `configuration`, `integration`, `report`, `data_object`, or `technical_flow` in v1. Those are better represented as knowledge block types or metadata inside the content.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "docs/FEATURE_KNOWLEDGE_DATABASE_PLAN.md#L145 Table: `internal_knowledge_feature_items`", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "internal-knowledge", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "60eb3b063824ed3fe112502a1f40780e5f0e2888e2f8a32d9e6775e4a931190c", "truncated": false}, "is_active": true}, {"id": "d91183dc-1cfd-5c31-95fa-9e897d8c2b57", "feature_slug": "internal-knowledge", "title": "Table: `internal_knowledge_blocks`", "content": "Each block explains one reusable piece of knowledge about a feature item.\n\n### Columns\n\n```text\nid\nfeature_item_id\ntitle\ncontent\ncontent_format\nknowledge_type\nperspectives\noutput_uses\nscope\nsource_ref\nmetadata\nis_active\nsearch_vector\ncreated_at\nupdated_at\n```\n\n### Column Notes\n\n```text\nfeature_item_id\nThe domain, feature, or sub-feature this block belongs to.\n\ntitle\nShort human-readable title.\n\ncontent\nThe actual explanation. V1 stores this as Markdown or plain text, not as one large flat document. Retrieval quality comes from small typed blocks plus metadata filters.\n\ncontent_format\n`markdown` or `plain_text`. Default is `markdown`.\n\nknowledge_type\nWhat kind of knowledge this block contains.\n\nperspectives\nArray of lenses this block serves, e.g. marketing, frontend, technical.\n\noutput_uses\nArray of downstream uses this block supports.\n\nscope\nWhich system area the block mainly applies to.\n\nsource_ref\nOptional source pointer, e.g. requirement doc, feature guide section, repo file, or MCP lookup note.\n\nmetadata\nJSON escape hatch for optional values. Do not overuse in v1.\n\nsearch_vector\nGenerated full-text search vector over title and content.\n```\n\nNo `language` field in v1. All content is English.\n\nNo `content_status` field in v1. Keep publishing/review workflow outside the first schema unless it becomes necessary.", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "docs/FEATURE_KNOWLEDGE_DATABASE_PLAN.md#L188 Table: `internal_knowledge_blocks`", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "internal-knowledge", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8b5e39e4b0ab75ddeb302b0cf1f94e4b6d235a8b195d25d0ae473c9443e74fbe", "truncated": false}, "is_active": true}, {"id": "ed6cd182-7418-59c5-979e-155bde32eee4", "feature_slug": "internal-knowledge", "title": "Table: `internal_knowledge_type_templates`", "content": "Stores expected content guidance per `knowledge_type`.\n\n### Columns\n\n```text\nknowledge_type\nexpected_content\nrecommended_scopes\nquality_rules\ncreated_at\nupdated_at\n```", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "docs/FEATURE_KNOWLEDGE_DATABASE_PLAN.md#L253 Table: `internal_knowledge_type_templates`", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "internal-knowledge", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f8f7d3757ec43ad35974416e7b1c7d777478eec3fb674eb0099876e09d24c269", "truncated": false}, "is_active": true}, {"id": "2d77197b-862c-5bc5-8640-e676ac44f9a7", "feature_slug": "internal-knowledge", "title": "Internal Knowledge Domain Reference", "content": "**Keywords:** internal_knowledge, feature knowledge, feature_items, knowledge_blocks, knowledge_type, perspectives, output_uses, downstream agent context, slide_generation, frontend_context, implementation_brief\n**Source:** `docs/FEATURE_KNOWLEDGE_DATABASE_PLAN.md`\n**Tables:** `internal_knowledge_feature_items`, `internal_knowledge_blocks`, `internal_knowledge_type_templates`\n| Function | Type | Purpose |\n|---|---|---|\n| `internal_knowledge_get_feature_tree` | Read RPC | Return active feature hierarchy, optionally rooted by slug |\n| `internal_knowledge_get_feature_context` | Read RPC | Return typed blocks for one feature, optionally including children and metadata filters |\n| `internal_knowledge_search_feature_knowledge` | Read RPC | Full-text search knowledge blocks with feature/type/perspective/use/scope filters |\n| `internal_knowledge_get_related_features` | Read RPC | Return parent/child relationships and related-feature blocks |\n| `internal_knowledge_list_knowledge_type_templates` | Read RPC | Return authoring templates by knowledge type |\n| `internal_knowledge_create_feature_item` | Edit RPC | Create a domain/feature/sub-feature item |\n| `internal_knowledge_update_feature_item` | Edit RPC | Update or deactivate a feature item |\n| `internal_knowledge_create_knowledge_block` | Edit RPC | Create a typed reusable knowledge block |\n| `internal_knowledge_update_knowledge_block` | Edit RPC | Update or deactivate a knowledge block |\n| `internal_knowledge_suggest_block_metadata` | Authoring RPC | Return recommended scopes and quality rules for a knowledge type |\n| `internal_knowledge_validate_knowledge_block` | Authoring RPC | Validate title/content/type/perspective/use/scope inputs before writing |\n**Key Business Rules (summary):**\n- Product hierarchy lives in `internal_knowledge_feature_items`; block content lives in `internal_knowledge_blocks`.\n- All schema objects and functions use the `internal_knowledge` prefix.\n- Content is stored as small Markdown/plain-text blocks, not one flat feature document.\n- Retrieval should filter by feature, `knowledge_type`, `perspectives`, `output_uses`, and `scope` before generating downstream outputs.\n- `internal_knowledge_blocks.search_vector` supports full-text search over title and content.\n- `internal_knowledge_type_templates` stores authoring guidance for each allowed `knowledge_type`.\n- Read functions are granted to `authenticated` and `service_role`; edit functions are granted to `service_role`.\n- Exact implementation object names in generated outputs should still be verified from live schema/code before implementation.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/internal-knowledge.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "internal-knowledge", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e54244389fd3ae5f64d8cae2ec93c34158a3375b13f41b76ba3773ec306ba08f", "truncated": false}, "is_active": true}, {"id": "a71c46d6-ea4d-582d-9f4f-fda83f374401", "feature_slug": "marketplace-integration", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Marketplace Settings | `/marketplace-settings` | `get_merchant_marketplace_channels()`, `fetchMarketplaceChannels()` |\n| Order Claims tab | `/marketplace-settings` (tab 0) | `bff_get_marketplace_order()` |\n| Marketplace Connections tab | `/marketplace-settings` (tab 1) | `get_merchant_marketplace_channels()` |\n| Dashboard modal | Modal on `/marketplace-settings` | `metabase-embed` edge function (dashboard ID 184) |\n\n### 4a. Connect a New Marketplace Channel\n\n1. From **Marketplace Settings**, switch to the **Marketplace Connections** tab\n2. Click **\"Create channel\"** → **Add Channel** modal opens\n3. Select a platform (TikTok Shop, Lazada, or Shopee) from the dropdown\n4. Enter a store name (required — identifies this connection in the admin panel)\n5. Platform-specific order statuses load via `get_platform_order_statuses()` — select which status triggers claim processing (radio buttons)\n6. Click **\"Connect →\"** — browser redirects to the platform''s OAuth authorization page\n7. Log in to the marketplace account and authorize access\n8. Platform redirects back to `/marketplace-settings` with an authorization code\n9. System exchanges the code for access/refresh tokens via the platform''s token exchange edge function\n10. On success: banner \"Successfully connected to {platform}!\", channel appears in the list, tab switches to Marketplace Connections\n\n### 4b. Manage Marketplace Connections\n\n1. **Marketplace Connections** tab shows all channels with platform icon, store name, external ID, and status badges\n2. **Platform filter tabs** at top: All / TikTok / Lazada / Shopee — filters the channel list\n3. Each channel row displays: platform badge, Active/Inactive status badge, environment badge (if not production)\n4. **Delete**: click the delete icon → confirmation modal → channel removed via `admin_delete_marketplace_channel()`\n\n### 4c. Search and View Marketplace Orders\n\n1. From **Marketplace Settings**, the **Order Claims** tab is the default view\n2. Select a platform from the dropdown (Shopee / TikTok / Lazada — required)\n3. Enter an order ID or number in the search field\n4. Click **Search** → system calls `bff_get_marketplace_order()`\n5. Result card displays: order number, platform icon, Claimed/Not Claimed badge, transaction date, order amount, order status, buyer info (username, phone), earned currency (if claimed), and a line items table (product name, amount)\n\n### 4d. View Dashboard & History\n\n1. Click **\"Dashboard & History\"** button (top-right) → modal opens with embedded Metabase dashboard\n2. Shows marketplace order processing analytics (orders per hour, shops processed, sync status)\n\n### 4e. Common Admin Mistakes\n\n- Selecting the wrong claim-from status → orders processed too early (before payment) or too late (customer already disengaged)\n- Not completing the OAuth flow → channel shows but token is inactive, no orders sync\n- Deleting a channel with unprocessed orders → those orders will not be retried", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/marketplace-integration.md#L62 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "05d64278b567fee31a58cbcf15c4c4bf9d703705c39597af84b6bc672a71a32b", "truncated": false}, "is_active": true}, {"id": "497dac7b-a716-56f0-aa1d-2a36b204b236", "feature_slug": "marketplace-integration", "title": "7. Business Rules", "content": "**Rule:** UNPAID orders are filtered at the webhook gateway (Hookdeck) and never enter the processing pipeline.\n**Example:** Shopee sends a webhook for a new UNPAID order → Hookdeck transformation returns `skip: true` → order is not published to Kafka.\n\n**Rule:** Orders are batched per shop with a maximum of 50 and a 2-minute cooldown. When 50 orders accumulate for one shop, they are processed immediately. If fewer than 50 accumulate and no new orders arrive, the batch is processed after the 2-minute timeout.\n**Example:** Shop A has 50 pending orders → batch triggers immediately. Shop A''s 51st order arrives 10 seconds later → waits 2 minutes for cooldown before next batch.\n\n**Rule:** Each shop processes independently with its own batch counter, cooldown timer, and API credentials.\n**Example:** Shop A reaching 50 orders does not trigger processing for Shop B, even if they belong to the same merchant.\n\n**Rule:** The claim-from status determines which orders qualify for loyalty processing. Only orders at or past this status are linked to purchase transactions.\n**Example:** Channel configured with claim-from = \"shipped\". A READY_TO_SHIP order is stored in order_ledger_mkp but does not create a purchase_ledger record until it reaches SHIPPED.\n\n**Rule:** Duplicate order webhooks are handled idempotently. Existing orders get a status update; new orders get a full insert with items.\n**Example:** Order SH001 arrives as READY_TO_SHIP (inserted), then arrives again as SHIPPED (status updated, no duplicate record).\n\n**Rule:** If the marketplace API returns an error during batch processing, unprocessed messages remain in Kafka and are retried on the next cycle. No data is lost.\n**Example:** Shopee API returns 429 → Inngest retries 3 times with backoff → if all fail, messages stay in Kafka for the next batch cycle.\n\n**Rule:** Buyer-to-member matching uses the buyer''s phone, email, or username from the marketplace order to find the corresponding CRM user. If no match is found, the order is stored but no points are awarded.\n**Example:** Marketplace buyer username \"john_doe\" has no matching CRM user → order is in order_ledger_mkp with synced_to_transaction = false.\n\n**Rule:** OAuth tokens are platform-specific and stored in `merchant_credentials` keyed by external_id (shop_id) and service_name (platform). Token refresh is handled per-platform.\n**Example:** Shopee token expires after 4 hours → refresh token is used to obtain a new access token automatically. If refresh fails, channel status becomes Inactive.\n\n**Rule:** The Add Channel flow stores configuration (store name, claim-from status) in browser sessionStorage before the OAuth redirect. After redirect, the token exchange function reads this configuration to complete channel setup.\n**Example:** Admin selects Shopee, enters \"My Store\", picks \"shipped\" → redirected to Shopee → returns → token exchange includes store_name and claim_from_status in the request.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L219 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7be06c9cff37040be292fb32ae83aec25faae7678e303b1df2aa3f1f2c2b46c1", "truncated": false}, "is_active": true}, {"id": "eb1c4745-d79e-549f-9043-bf2b3b96ddfd", "feature_slug": "marketplace-integration", "title": "3. Configuration Reference", "content": "### Channel Connection\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Platform | Which marketplace to connect | Shopee / Lazada / TikTok | Required |\n| Store name | Human-readable label for this connection | \"My Shopee TH\" | Required |\n| Claim-from status | Order status that triggers loyalty processing | \"shipped\" | First available status for platform |\n\n### Pipeline Settings (System-Level)\n\n| Setting | What it controls | Value |\n|---|---|---|\n| Batch size | Orders per API call | 50 |\n| Batch timeout | Max wait before processing partial batch | 2 minutes |\n| Rate limit | API calls per minute per shop | 30 |\n| Concurrent shops | Parallel processing limit | 10 |\n| Kafka retention | How long raw events are kept | 7 days |\n\n### Channel Properties (Read-Only After Connection)\n\n| Property | Description | Example |\n|---|---|---|\n| External ID | Shop ID on the marketplace platform | \"1391650466\" |\n| Token status | Whether OAuth credentials are valid | Active / Inactive |\n| Environment | Production or sandbox | \"production\" |\n| Platform image | Platform icon URL for display | Shopee logo URL |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/marketplace-integration.md#L33 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4ddba668904297aab4483fd2f0b0eaac15e4bc574c783dda597435d60f6b2d17", "truncated": false}, "is_active": true}, {"id": "a2e9c532-ff7c-569b-9983-1187b8231ed7", "feature_slug": "marketplace-integration", "title": "2. Key Concepts", "content": "**Marketplace Channel** — A connection between one merchant shop on an external platform and the CRM. Each channel stores OAuth credentials, a store name, and configuration for order import. Example: \"My Shopee TH Store\" linked to Shopee shop ID 1391650466.\n\n**Supported Platforms** — Three marketplaces are currently supported: Shopee, Lazada, and TikTok Shop. Each uses OAuth for authorization and has a platform-specific adapter for order data normalization.\n\n**Order Sync** — The automatic process of receiving marketplace order webhooks, batching them, calling the platform API for full details, and storing them in the CRM. Orders sync within 2–5 minutes of a status change on the marketplace.\n\n**Order Claim** — The link between a synced marketplace order and the loyalty system. Once an order is \"claimed,\" it becomes a purchase transaction that can trigger point awards. The claim happens automatically when the order reaches the configured status threshold.\n\n**Claim-From Status** — The marketplace order status at which the system begins processing for loyalty. Configured per channel during setup. Example: \"shipped\" means orders are claimed when the marketplace marks them as shipped, not before.\n\n**Platform Order Statuses** — Each marketplace has its own status progression. Shopee: UNPAID → READY_TO_SHIP → SHIPPED → COMPLETED → (CANCELLED/RETURNED). Statuses below the claim threshold (e.g., UNPAID) are filtered out at the webhook gateway.\n\n**Order Ledger (Marketplace)** — The `order_ledger_mkp` table storing synced order headers. Contains order amounts, buyer info, marketplace status, and a flag indicating whether the order has been synced to a purchase transaction.\n\n**Batch Processing** — Orders are grouped per shop (up to 50) before calling the marketplace API. This reduces API calls by 50x compared to processing each order individually and respects platform rate limits.\n\n**Platform Adapter** — A module that translates platform-specific API formats into the CRM''s common order format. Adding a new marketplace means writing a new adapter — no changes to the core pipeline.\n\n**Token Exchange** — The OAuth flow where the admin authorizes CRM access to their marketplace shop. The platform returns a code, which the system exchanges for access and refresh tokens stored in `merchant_credentials`.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "131dab24d6bce08c58c191df489c989164de06ab6c693b5e7f4d818f955787af", "truncated": false}, "is_active": true}, {"id": "25fb067e-e4a3-50f3-9579-22cbb115ff69", "feature_slug": "marketplace-integration", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"When your customers buy from your Shopee, Lazada, or TikTok Shop store, they automatically earn loyalty points — no manual claiming needed. The system syncs orders and awards points within minutes.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Customer didn''t receive points for marketplace order\" | Check if the channel is Active (token not expired). Search the order in Order Claims tab — if \"Not Claimed,\" the order hasn''t reached the configured claim-from status yet. If not found, the order may not have synced (webhook delay or platform issue). |\n| \"Order shows ''Not Claimed'' even though it''s completed\" | The claim-from status may be set to a later stage than the current order status. Or the buyer info doesn''t match any CRM user — points can''t be awarded without a matched member. |\n| \"Channel shows Inactive status\" | OAuth token has expired or was revoked. Admin needs to delete the channel and reconnect through the OAuth flow. |\n| \"Points were awarded for a cancelled order\" | If claim-from status is before COMPLETED (e.g., \"shipped\"), a later cancellation won''t automatically reverse points. This requires manual review. |\n| \"How long until points appear?\" | Orders sync within 2–5 minutes of the marketplace status change. Currency processing adds another 30–60 seconds. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L134 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0f77d41bc069170d9d3f0d5f0967956490ed3bfba1569f5cf930cca7979623cb", "truncated": false}, "is_active": true}, {"id": "cfc7e7a4-16fa-590f-b303-0089f3059c76", "feature_slug": "marketplace-integration", "title": "1. Overview", "content": "Marketplace Integration connects the CX Platform to external e-commerce marketplaces — Shopee, Lazada, and TikTok Shop — so that orders placed on those platforms automatically flow into the loyalty system. When a customer buys from a merchant''s Shopee store, the order is ingested, matched, and processed to award loyalty points without any manual step by the member or merchant staff.\n\nThe integration solves a specific problem: merchants sell on multiple online channels, but loyalty programs traditionally only track in-store or native-app purchases. By syncing marketplace orders, merchants can reward customers across all sales channels — unifying the earn side of the loyalty loop regardless of where the purchase happens.\n\nThe pipeline is event-driven. Marketplace webhooks arrive via Hookdeck, flow through Kafka (partitioned per shop), get batched by Inngest (up to 50 orders per batch, 2-minute cooldown per shop), and land in the CRM database. From there, the existing purchase-to-currency flow takes over — triggering point awards, tier evaluation, and mission progress just like any in-store transaction.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7ba809665405bcbce4c859ab441986c4e55130222fc916c784f0f1c55ab0252b", "truncated": false}, "is_active": true}, {"id": "98a61658-193d-5f6d-9fcc-4047219555ae", "feature_slug": "marketplace-integration", "title": "8. Related Features", "content": "| Feature | Connection to Marketplace Integration |\n|---|---|\n| Purchase Transactions | Claimed marketplace orders become purchase_ledger records, triggering the standard currency/tier/mission cascade. See `Purchase_Transaction.md`. |\n| Currency | Points are awarded from marketplace purchases through the same earn flow as in-store purchases. See `Currency.md`. |\n| Tier | Marketplace purchase amounts contribute to tier metric calculations (sales, order count). See `Tier.md`. |\n| Rewards | Rewards can be distributed to external storefronts via `online_store[]` — the outbound counterpart to marketplace order ingestion. See `Reward.md`. |\n| Mission | Marketplace purchases can satisfy mission conditions of type \"purchase\" when product/amount filters match. See `Mission.md`. |\n| Store Classification | Marketplace shops can be treated as store locations for store-attribute-based earn rules. See `Store_Attribute_Classification.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L248 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "34e85572709bf5c276ac0a255acfe50b64a9113af5b35da9b88566ef1292268b", "truncated": false}, "is_active": true}, {"id": "83521804-585b-5825-a880-c33b173fde0a", "feature_slug": "marketplace-integration", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Channel connected, token Active | Orders from that shop sync automatically within 2–5 minutes |\n| Channel connected, token Inactive | No orders sync; admin must reconnect |\n| Claim-from status = \"shipped\" | UNPAID and READY_TO_SHIP orders are ingested but not claimed; SHIPPED triggers claim |\n| No CRM user matches buyer info | Order syncs and stores in order_ledger_mkp but no points awarded |\n| 50+ orders arrive rapidly for one shop | Inngest batches first 50, processes them, then batches the remainder after 2-minute cooldown |\n| Fewer than 50 orders arrive, then no more | After 2-minute timeout, partial batch is processed |\n| Platform returns 429 (rate limited) | Inngest retries with exponential backoff (3 attempts) |\n| Duplicate order webhook | Unique constraint on order_sn prevents duplicate storage |\n| Order status updated (e.g., SHIPPED → COMPLETED) | Existing order_ledger_mkp record updated; no duplicate insert |\n\n**Business rules as assertions:**\n\n- ASSERT: UNPAID orders are filtered at the Hookdeck gateway and never reach Kafka\n- ASSERT: Orders are batched per shop_id — Shop A''s batch never contains Shop B''s orders\n- ASSERT: Batch size never exceeds 50 orders per API call\n- ASSERT: Cooldown of 2 minutes is enforced between batches for the same shop\n- ASSERT: OAuth token exchange uses single-use authorization codes — a second call with the same code fails\n- ASSERT: Deleting a channel calls `admin_delete_marketplace_channel()` and removes it from the channel list\n- ASSERT: Order search requires platform selection — searching without platform shows \"Please select a platform first\" error\n- ASSERT: Claimed orders show \"Claimed\" badge and earned currency amount in the order result card\n- ASSERT: Add Channel modal requires both platform and store name — Connect button is disabled until both are provided\n- ASSERT: Platform filter tabs on Marketplace Connections show correct subset (e.g., \"Shopee\" tab shows only Shopee channels)\n\n**Error states and cross-feature scenarios to test:**\n\n- OAuth redirect fails (user denies access) → error banner shown, no channel created\n- Token expires after initial connection → channel shows \"Inactive\" badge, orders stop syncing\n- Order with buyer phone matching two CRM users → verify which user gets the points (first match behavior)\n- Marketplace order triggers currency award → verify points appear in member''s wallet history with correct source\n- Marketplace order satisfies mission condition → verify mission progress increments\n- High-volume test: send 200 orders for one shop → verify 4 batches processed (50+50+50+50) with cooldown between each\n\n**Status model (order lifecycle):**\n\n| Track | Field | Values | Meaning |\n|---|---|---|---|\n| Platform status | `order_status` | UNPAID → READY_TO_SHIP → SHIPPED → COMPLETED | Marketplace-side order progress |\n| Platform status (alt) | `order_status` | → CANCELLED, RETURNED | Failure/reversal paths |\n| CRM sync | `synced_to_transaction` | `false` → `true` | Whether order has been linked to a purchase transaction |\n| CRM status | `status` | pending → completed | Purchase transaction status after sync |\n\n- `synced_to_transaction = false` means the order is stored but not yet processed for loyalty\n- `synced_to_transaction = true` means a purchase_ledger record exists and currency processing has been triggered\n- Platform `order_status` and CRM `status` are independent — the platform status reflects marketplace state, CRM status reflects loyalty processing state", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L134 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d59049e6f1a8921c0c34dc1f21488880d51d19de6a69cf68c200ffe15f773fbe", "truncated": false}, "is_active": true}, {"id": "fccccba3-2943-5a1a-976b-ee217cd79879", "feature_slug": "marketplace-integration", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| (No marketplace-specific member pages) | — | — |\n\nThe member experience for marketplace integration is entirely passive. There are no member-facing screens for marketplace orders. The flow is:\n\n1. Member makes a purchase on a connected marketplace (Shopee, Lazada, TikTok Shop)\n2. The order syncs automatically through the webhook pipeline (2–5 minutes)\n3. When the order reaches the configured claim-from status, it is processed as a purchase transaction\n4. Points appear in the member''s wallet via the standard currency award flow\n5. The transaction is visible in the member''s purchase/earn history alongside in-store purchases\n\nThe member does not need to link accounts, submit order numbers, or take any action. Point attribution uses the buyer information from the marketplace order (phone, email, or username) matched against the CRM user database.", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/marketplace-integration.md#L114 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2e8d14b5ae5d4d6d55544ae48306ad8e011b66b0f7f902996b33243c4a47fe0e", "truncated": false}, "is_active": true}, {"id": "9be17b7c-49ee-54b5-bb71-900b9692425a", "feature_slug": "marketplace-integration", "title": "6b. For Marketing", "content": "**Value proposition:** Marketplace Integration extends the loyalty program to every sales channel. Customers earn points whether they buy in-store, on the native app, or through Shopee/Lazada/TikTok Shop — removing the friction that causes marketplace-only customers to disengage from loyalty programs.\n\n**Use-case stories:**\n\n1. **Fashion brand on Shopee** — 60% of sales happen on Shopee. Before integration, those customers never joined the loyalty program. Now they automatically earn points on every order, driving repeat purchases and eventual migration to the branded app where margins are higher.\n\n2. **Multi-platform retailer** — Sells on Shopee, Lazada, and TikTok simultaneously. All three channels feed into one loyalty account, so a customer''s total spending across platforms counts toward tier progression. A Gold-tier member who splits purchases across channels still gets Gold-tier earn rates everywhere.\n\n**Metrics merchants care about:** Orders synced per day, claim success rate, platform breakdown (Shopee vs. Lazada vs. TikTok), points awarded from marketplace vs. other channels, customer match rate (marketplace buyers who are also CRM members), average order value by platform.\n\n**Differentiators to highlight:**\n- **Zero member effort** — no order claiming, no account linking, no screenshots. Points just appear.\n- **Multi-platform unification** — Shopee + Lazada + TikTok all feed one loyalty account, so total spending is visible.\n- **Near-real-time** — points within minutes of the order status change, not end-of-day batch.\n- **Platform-agnostic architecture** — adding a new marketplace takes hours, not weeks.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/marketplace-integration.md#L134 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "marketplace-integration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "022df896a8c18934fbafc1bba9bd05b83c6d20fa6fd7243933373b1ad1f2a9dc", "truncated": false}, "is_active": true}, {"id": "6d0f424b-d8fa-574b-a4cd-608ff48aaf92", "feature_slug": "missions", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Mission List | `/mission-list` | `mission` table direct query |\n| Mission Settings (create) | `/mission-settings/new` | `bff_get_mission_details_conditions_limits(mode=''new'')` |\n| Mission Settings (edit) | `/mission-settings/{id}` | `bff_get_mission_details_conditions_limits(mode=''edit'', id)` |\n\n### 4a. Create a New Mission\n\n1. From **Mission List**, click **\"Create mission\"** button (top-right)\n2. **Mission Settings** opens in create mode — empty form\n3. Fill Basic Info: name (required), code (required), select type (Standard or Milestone)\n4. Set activation type and claim type; configure reset frequency if needed\n5. Add conditions: select condition type, measurement type, target value; add product/category/brand/store filters as needed\n6. For Milestone type: define levels with names, badge images, and one condition per level\n7. Add outcomes: select outcome type (points/tickets/reward), set amount, link to milestone level if applicable\n8. Optionally configure progress and claim limits\n9. Set start/end dates, toggle is_active\n10. Click **\"Save\"** → calls `bff_upsert_mission` → on success: redirect to **Mission List**\n\n### 4b. Edit an Existing Mission\n\n1. From **Mission List**, click any mission row\n2. **Mission Settings** opens in edit mode — form pre-populated with all conditions, outcomes, and limits\n3. Modify any fields — all sections are editable\n4. Click **\"Save\"** to update\n\n### 4c. Manage the Mission List\n\n1. **Mission List** displays an IndexTable with columns: Name, Type (badge), Status (badge), Activation (badge), Claim (badge), Start date, End date, Delete action\n2. Status badges: Active (green), Inactive (neutral), Scheduled (blue), Expired (red)\n3. **Delete**: click delete icon → confirmation modal (\"This will permanently delete this mission and all its conditions, outcomes, and limits\") → cascading delete of conditions, outcomes, limit_progress, limit_claim, then the mission\n4. Empty state shows CTA: \"Create your first mission to engage users with challenges and rewards\"\n\n### 4d. Common Admin Mistakes\n\n- Setting `activation_type = manual` but not surfacing the join button in the member app → members can''t participate\n- Creating a milestone mission with reset frequency → constraint violation (milestones don''t reset)\n- Adding product filters with AND operator when products come from different purchases → condition never completes\n- Setting `allow_progress_loop = false` on a daily-reset mission → mission can only complete once despite resetting\n- No outcomes configured → mission completes but grants nothing", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/missions.md#L126 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "missions", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "50c98344b448c25b5d35c64473aa8ff52b5acebba9af3a104036d8440c8fe4ba", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
